-- ── Consensus (world-wide game parameters) ────────────────────────────────────
INSERT OR IGNORE INTO consensus (key, value, value_type, name, purpose) VALUES
  ('CAT.COOLDOWN_HOUR_BETWEEN_CARE',  '1',  'NUMBER', 'Care cooldown',     'Minimum cooldown time (in hours) between caring for your cat'),
  ('CAT.GROWTH_PER_CARE',     '1',  'NUMBER', 'Growth stat gained per care', 'Growth stat gained when caring for your cat'),
  ('CAT.EMOTION_PER_CARE',    '5',  'NUMBER', 'Emotion stat gained per care', 'Emotion stat gained when caring for your cat'),
  ('CAT.EMOTION_DECREASE',    '10', 'NUMBER', 'Emotion decrease per cycle', 'Emotion stat lost per cycle when you do not care for your cat'),
  ('CAT.EMOTION_DECREASE_FREQUENCY_HOUR', '12', 'NUMBER', 'Emotion decrease frequency (hours)', 'How often (in hours) emotion decreases if cat was not cared for'),
  ('CAT.MAX_GROWTH',          '100', 'NUMBER', 'Maximum growth stat', 'Maximum growth stat your cat can have')
;

-- ── Big5 Personality Traits ────────────────────────────────────
-- Goldberg, L. R. (1992). The development of markers for the Big-Five factor structure. Psychological Assessment, 4, 26-42.
-- https://ipip.ori.org/new_ipip-50-item-scale.htm
INSERT OR IGNORE INTO personality_question (id, text, keyed, domain, description_level_1, description_level_2, description_level_3, description_level_4, description_level_5) VALUES
  ('019e436a-48cc-71e8-ab2a-732946ec83ff', 'Am the life of the party', 'plus', 'extraversion', 'You’d rather stay home with a book than be the center of attention. (Party? What party?)', 'You show up but mostly observe from the corner with snacks.', 'Sometimes you chat, sometimes you hide. Depends on the vibe and caffeine level.', 'You enjoy talking to people and usually have a good time at gatherings.', 'You walk in and the energy level immediately goes up. You ARE the party.'),
  ('019e436a-48cd-72e1-b686-f8b13495fd25', 'Feel little concern for others', 'minus', 'agreeableness', 'You cry during dog food commercials and offer help to strangers.', 'You generally care about people’s feelings.', 'You care… when it’s convenient and not too emotionally draining.', 'You mostly focus on your own stuff and don’t get too involved.', '“Not my circus, not my monkeys” is your life motto.'),
  ('019e3e79-1504-7aa9-be84-9d0fed51eb38', 'Am always prepared', 'plus', 'conscientiousness', 'You once showed up to a camping trip with only flip-flops and hope.', 'You usually wing it and somehow survive.', 'You prepare when it matters, otherwise… meh.', 'You like having a plan and backup plans.', 'Your backpack has a backpack. You’re prepared for the apocalypse.'),
  ('019e3e79-1504-7aa9-be86-add2934df436', 'Get stressed out easily', 'plus', 'neuroticism', 'A flat tire is just an opportunity to practice patience.', 'You stay pretty calm even when things go wrong.', 'Stress happens, but you manage most of the time.', 'Small things can ruin your day pretty quickly.', 'Your brain treats “maybe” as a five-alarm fire.'),
  ('019e436a-48ce-7053-8703-70fd3e8f0d1e', 'Have a rich vocabulary', 'plus', 'openness', 'You call everything “thingy” or “whatchamacallit.”', 'You know enough words but don’t flex them.', 'Average vocabulary, gets the job done.', 'You enjoy using precise and interesting words.', 'You dropped “sesquipedalian” in casual conversation… unironically.'),
  ('019e436a-48d0-7754-b3b5-1f1f7b5364dd', 'Don''t talk a lot', 'minus', 'extraversion', 'You talk so much your friends need a mute button.', 'You’re quite chatty in most situations.', 'You talk when you have something to say.', 'You prefer listening over speaking.', 'You once went a whole day without saying more than 10 words.'),
  ('019e436a-48d1-71f4-a4c4-c3d5dd01bd8a', 'Am interested in people', 'plus', 'agreeableness', 'People are exhausting. You’d rather talk to your plants.', 'You’re selective about whose life story you want to hear.', 'Some people yes, most people… maybe later.', 'You genuinely enjoy learning about others.', 'You’re the person who remembers everyone’s dog’s birthday.'),
  ('019e3e79-1504-7aa9-be86-f4172cdf69cb', 'Leave my belongings around', 'minus', 'conscientiousness', 'Your desk looks like a minimalist Instagram photo.', 'You usually clean up after yourself.', 'Sometimes tidy, sometimes a mild disaster zone.', 'Things tend to pile up in creative locations.', 'You have a “floor wardrobe” and lost your keys… again.'),
  ('019e436a-48d2-73b0-b7d3-d2306659faac', 'Am relaxed most of the time', 'minus', 'neuroticism', 'Your resting heart rate is “mild panic.”', 'You get tense quite often.', 'Chill until something triggers you.', 'You stay pretty calm day-to-day.', 'Zen master level. Nothing fazes you.'),
  ('019e3e79-1504-7aa9-be86-6ad6a7aecf58', 'Have difficulty understanding abstract ideas', 'minus', 'openness', 'You live in the world of metaphors and hypotheticals.', 'Abstract concepts are fun for you.', 'Depends on the topic.', 'You prefer concrete, practical ideas.', '“What does this even mean?” is your default reaction to philosophy.'),
  ('019e3e79-1504-7aa9-be84-d5b49bde92f6', 'Feel comfortable around people', 'plus', 'extraversion', 'Social situations feel like being thrown into a shark tank.', 'You need time to warm up.', 'Comfortable with friends, awkward with strangers.', 'You generally feel at ease in social settings.', 'You could make friends with a lamppost.'),
  ('019e3e79-1504-7aa9-be86-4860c888630d', 'Insult people', 'minus', 'agreeableness', 'You’d rather compliment someone’s shoes than criticize them.', 'You avoid hurting others’ feelings.', 'Only when they really deserve it.', 'You can be blunt or sarcastic.', 'Your roasts could be a Netflix special.'),
  ('019e436a-48d3-75ea-9992-2ecefbd713fc', 'Pay attention to details', 'plus', 'conscientiousness', 'You once put salt in your coffee twice.', 'Big picture person. Details are annoying.', 'You catch some details, miss others.', 'You notice the little things.', 'You spot typos from three rooms away.'),
  ('019e3e79-1504-7aa9-be83-de4f901b42f1', 'Worry about things', 'plus', 'neuroticism', 'You live in the moment. Tomorrow can worry about itself.', 'You worry only about important stuff.', 'Average worrier.', 'You tend to overthink possible bad outcomes.', 'You’ve already mentally rehearsed 47 disasters for next Tuesday.'),
  ('019e3e79-1504-7aa9-be83-e89e502123d5', 'Have a vivid imagination', 'plus', 'openness', 'Your daydreams are just about food and sleep.', 'Imagination is okay, but you stay realistic.', 'Sometimes you zone out creatively.', 'You often picture wild scenarios.', 'Your brain is a 4K IMAX theater running 24/7.'),
  ('019e436a-48d5-77a1-98b9-f6d9ac7ccbca', 'Keep in the background', 'minus', 'extraversion', 'You were born to be in the spotlight.', 'You enjoy being noticed.', 'Depends on the situation.', 'You prefer staying low-key.', 'You’re basically a ninja in social settings.'),
  ('019e436a-48d6-74ef-ad02-c16246903b39', 'Sympathize with others'' feelings', 'plus', 'agreeableness', '“Just stop crying and fix it” is your go-to advice.', 'You’re not the most empathetic person.', 'You sympathize sometimes.', 'You easily feel what others feel.', 'You absorb emotions like an emotional sponge.'),
  ('019e436a-48d7-763b-9846-398f0d66a415', 'Make a mess of things', 'minus', 'conscientiousness', 'You color-code your chaos and still make it look organized.', 'You rarely mess things up.', 'It happens occasionally.', 'Things tend to get disorganized around you.', 'You could turn a simple task into performance art of disaster.'),
  ('019e436a-48d9-703b-af22-c38ed477e480', 'Seldom feel blue', 'minus', 'neuroticism', 'You have seasonal depression… in all seasons.', 'You feel down fairly often.', 'Mood is usually stable.', 'You’re generally in a good mood.', 'You’re basically a walking ray of sunshine.'),
  ('019e436a-48da-752b-b256-eab3e38f49e7', 'Am not interested in abstract ideas', 'minus', 'openness', 'You debate philosophy in the shower.', 'You enjoy deep, theoretical topics.', 'Sometimes yes, sometimes no.', 'You prefer practical over abstract.', '“If it’s not useful right now, I don’t care.”'),
  ('019e436a-48db-76b1-a681-adebb32de81c', 'Start conversations', 'plus', 'extraversion', 'You wait for others to speak first… always.', 'You join conversations but rarely start them.', 'You start them when comfortable.', 'You easily initiate talks.', 'You could start a conversation with a rock.'),
  ('019e3e79-1504-7aa9-be86-9b30d262f91e', 'Am not interested in other people''s problems', 'minus', 'agreeableness', 'You’re everyone’s unpaid therapist.', 'You care about others’ issues.', 'Depends on how close you are.', 'You prefer to stay out of drama.', '“That sounds like a you problem.”'),
  ('019e436a-48dc-72ca-be46-fc6e601a9fb0', 'Get chores done right away', 'plus', 'conscientiousness', 'Procrastination is your love language.', 'You do them… eventually.', 'Sometimes immediately, sometimes later.', 'You usually finish chores quickly.', 'You finish chores before they even become chores.'),
  ('019e436a-48de-7226-9a9d-957e9d6998e5', 'Am easily disturbed', 'plus', 'neuroticism', 'You remain calm even when everything is on fire.', 'Small things rarely bother you.', 'You get annoyed sometimes.', 'You get disturbed pretty easily.', 'Everything bothers you. Everything.'),
  ('019e436a-48df-71d5-9cf7-bafa329b277a', 'Have excellent ideas', 'plus', 'openness', 'Ideas? What ideas?', 'You get occasional decent ideas.', 'You have some good ideas now and then.', 'You often come up with creative ideas.', 'Your brain is a nonstop idea fireworks show.'),
  ('019e436a-48e0-7271-96cb-b96758868123', 'Have little to say', 'minus', 'extraversion', 'You talk so much your friends need a mute button.', 'You’re quite chatty in most situations.', 'You talk when you have something to say.', 'You prefer listening over speaking.', 'You once went a whole day without saying more than 10 words.'),
  ('019e436a-48e1-72c6-983d-1de7c6b1dd1f', 'Have a soft heart', 'plus', 'agreeableness', 'You’re emotionally bulletproof.', 'You’re not easily moved.', 'You feel for others sometimes.', 'You’re quite compassionate.', 'Your heart is made of marshmallow.'),
  ('019e3e79-1504-7aa9-be85-179a657a6fba', 'Often forget to put things back in their proper place', 'minus', 'conscientiousness', 'Everything always goes back to its exact spot immediately.', 'You usually remember to tidy up.', 'You forget sometimes.', 'Things often stay where you left them.', 'Your room looks like a post-apocalyptic thrift store.'),
  ('019e436a-48e3-71b1-b256-df708b955c48', 'Get upset easily', 'plus', 'neuroticism', 'It takes a lot to upset you.', 'You stay calm most of the time.', 'You get irritated occasionally.', 'You get upset pretty easily.', 'Your emotional stability is held together by tape.'),
  ('019e436a-48e4-7330-a0cb-29d5015a48a4', 'Do not have a good imagination', 'minus', 'openness', 'Your imagination runs wild 24/7.', 'You have a pretty active imagination.', 'Average imagination.', 'You’re not very imaginative.', 'You think a potato is just a potato.'),
  ('019e3e79-1504-7aa9-be84-fa81be886025', 'Talk to a lot of different people at parties', 'plus', 'extraversion', 'You hug the wall like it’s your best friend.', 'You talk to a few people you already know.', 'You talk to some new people if the mood is right.', 'You enjoy chatting with many different people.', 'You’re the human equivalent of group chat.'),
  ('019e436a-48e5-715d-bc6e-f4dcd6259a79', 'Am not really interested in others', 'minus', 'agreeableness', 'You’re deeply curious about everyone’s life.', 'You care about others quite a bit.', 'You’re interested sometimes.', 'You’re not very interested in others.', 'Other people? What other people?'),
  ('019e436a-48e6-74da-993a-799f9030748f', 'Like order', 'plus', 'conscientiousness', 'Chaos is your comfort zone.', 'Order is nice but not necessary.', 'You like some order.', 'You prefer things organized.', 'Your life runs on color-coded spreadsheets.'),
  ('019e436a-48e8-76cd-bfdd-2012b81eabd5', 'Change my mood a lot', 'plus', 'neuroticism', 'Your mood is rock-solid.', 'Your mood is fairly stable.', 'Your mood changes sometimes.', 'Your mood changes quite often.', 'You have more mood swings than a playground.'),
  ('019e436a-48e9-7152-b948-bfccd4663b51', 'Am quick to understand things', 'plus', 'openness', 'You need things explained multiple times.', 'You understand most things at normal speed.', 'You catch on fairly quickly.', 'You understand things fast.', 'You get it before the sentence is even finished.'),
  ('019e436a-48ea-731a-ad47-8af04a65ad03', 'Don''t like to draw attention to myself', 'minus', 'extraversion', 'You love being the center of attention.', 'You don’t mind attention.', 'Depends on the situation.', 'You prefer not to stand out.', 'You’d rather blend into the wallpaper.'),
  ('019e436a-48ec-7447-a668-e97a1a4dd99f', 'Take time out for others', 'plus', 'agreeableness', 'Your time is strictly yours.', 'You help when it’s easy.', 'You help when you can.', 'You often make time for others.', 'You’d drop everything to help someone.'),
  ('019e436a-48ed-776f-9023-f13681783dda', 'Shirk my duties', 'minus', 'conscientiousness', 'You never avoid responsibilities.', 'You rarely avoid duties.', 'You avoid them sometimes.', 'You often put off responsibilities.', 'Duties? What duties?'),
  ('019e436a-48ee-702e-a1de-58412214d898', 'Have frequent mood swings', 'plus', 'neuroticism', 'Your mood is extremely stable.', 'Your mood doesn’t swing much.', 'You have occasional mood changes.', 'Your mood swings quite a bit.', 'You have more mood swings than a playground.'),
  ('019e436a-48ef-7567-b588-f3e30a8707f8', 'Use difficult words', 'plus', 'openness', 'You keep your words simple.', 'You use normal vocabulary.', 'You use some advanced words.', 'You enjoy using sophisticated words.', 'You use words that make dictionaries nervous.'),
  ('019e436a-48f1-75d9-be61-8c39549504eb', 'Don''t mind being the center of attention', 'plus', 'extraversion', 'Being the center of attention feels terrifying.', 'You’d rather not be noticed.', 'It depends on the situation.', 'You’re okay with attention.', 'You love being in the spotlight.'),
  ('019e3e79-1504-7aa9-be85-2e578b259fde', 'Feel others'' emotions', 'plus', 'agreeableness', 'You rarely notice how others feel.', 'You notice emotions sometimes.', 'You can usually tell how people feel.', 'You easily pick up on others’ emotions.', 'You feel other people’s emotions more than your own.'),
  ('019e436a-48f2-7785-8175-67e006ff8f81', 'Follow a schedule', 'plus', 'conscientiousness', 'A schedule? That’s cute.', 'You follow a loose plan.', 'You sometimes follow a schedule.', 'You usually stick to your schedule.', 'Your life is color-coded and timestamped.'),
  ('019e3e79-1504-7aa9-be84-f1c6a90361c7', 'Get irritated easily', 'plus', 'neuroticism', 'It takes a lot to irritate you.', 'You stay calm most of the time.', 'You get irritated occasionally.', 'You get irritated quite easily.', 'Everything and everyone irritates you.'),
  ('019e436a-48f3-723c-9b44-06c55122aa68', 'Spend time reflecting on things', 'plus', 'openness', 'You live completely in the moment.', 'You reflect occasionally.', 'You think about things sometimes.', 'You enjoy reflecting on life.', 'Your brain is a 24/7 philosophy podcast.'),
  ('019e436a-48f5-7360-9c4b-748aaa8e8917', 'Am quiet around strangers', 'minus', 'extraversion', 'You become a social butterfly with strangers.', 'You warm up quickly.', 'You’re somewhat quiet at first.', 'You tend to be quiet around strangers.', 'You go full silent mode with new people.'),
  ('019e436a-48f6-70a3-8d2e-f56bbfc77700', 'Make people feel at ease', 'plus', 'agreeableness', 'People feel awkward around you.', 'You’re neutral in social comfort.', 'You can make people comfortable sometimes.', 'You’re good at making others feel at ease.', 'You’re a walking comfort blanket.'),
  ('019e436a-48f7-7552-988c-7ed5e6bb4259', 'Am exacting in my work', 'plus', 'conscientiousness', 'You do the bare minimum.', 'You do decent work.', 'You’re reasonably careful.', 'You pay close attention to quality.', 'Your work is obsessively precise.'),
  ('019e3e79-1504-7aa9-be84-2a6fa2c150d9', 'Often feel blue', 'plus', 'neuroticism', 'You’re almost always in a good mood.', 'You rarely feel down.', 'You feel blue sometimes.', 'You often feel down.', 'Sadness is your default setting.'),
  ('019e436a-48f8-77f3-852b-20c0b26b8bf6', 'Am full of ideas', 'plus', 'openness', 'Your idea tank is usually empty.', 'You get ideas now and then.', 'You have a decent number of ideas.', 'You’re often full of ideas.', 'Your brain throws idea parties every hour.')
;
